INSERT INTO sources (
  id,
  name,
  kind,
  countries,
  roles,
  method,
  config,
  trust,
  status,
  yield_stats
)
SELECT
  md5('jobsniper-source:' || seed_key)::uuid,
  name,
  kind,
  countries,
  roles,
  method,
  config,
  trust,
  status,
  '{"itemsSeen":0,"relevantJobs":0,"duplicateJobs":0,"failures":0,"lastYieldAt":null}'::jsonb
FROM seed
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  kind = EXCLUDED.kind,
  countries = EXCLUDED.countries,
  roles = EXCLUDED.roles,
  method = EXCLUDED.method,
  config = EXCLUDED.config,
  trust = EXCLUDED.trust,
  status = EXCLUDED.status,
  updated_at = now();
